window.PORTFOLIO_PAGE_TRANSLATIONS = [["Claude course \u2014 practice after the session","Claude \uac15\uc758 \u2014 \uac15\uc758 \ud6c4 \ub530\ub77c \ud574\ubcf4\uae30"],["Practice after the session","\uac15\uc758 \ud6c4 \ub530\ub77c \ud574\ubcf4\uae30"],["Repeat the workflow from the course yourself. Seven steps, about 30\u201345 minutes.","\uac15\uc758\uc5d0\uc11c \ubcf8 \ud750\ub984\uc744 \ubcf8\uc778 \uc190\uc73c\ub85c \ud55c \ubc88 \ub354 \ub530\ub77c\uac04\ub2e4. 7\ub2e8\uacc4, \uc57d 30~45\ubd84."],["Start over","\ucc98\uc74c\ubd80\ud130"],["Prepare \u2014 open Claude.ai and get the folder","\uc900\ube44 \u2014 Claude.ai \uc5f4\uace0 \ud3f4\ub354 \ubc1b\uae30"],["Log in and have the materials folder shared by the instructor ready.","\ub85c\uadf8\uc778\ud558\uace0, \uac15\uc0ac\uac00 \uacf5\uc720\ud55c \uc790\ub8cc \ud3f4\ub354\ub97c \uc190\uc5d0 \ub454\ub2e4."],["\u2014 log in here.","\uc5d0 \ub85c\uadf8\uc778\ud55c\ub2e4."],["In the course folder, locate","\uac15\uc758\uc5d0\uc11c \ubc1b\uc740 \ud3f4\ub354 \uc548"],[" and","\uc640"],[".","\uc758 \uc704\uce58\ub97c \ud655\uc778\ud55c\ub2e4."],["Menus may differ depending on your paid plan and organizational policy.","\uc720\ub8cc \ud50c\ub79c \uc5ec\ubd80\uc640 \uc870\uc9c1 \uc815\ucc45\uc5d0 \ub530\ub77c \ubcf4\uc774\ub294 \uba54\ub274\uac00 \ub2e4\ub97c \uc218 \uc788\uc74c\uc744 \uc778\uc9c0\ud55c\ub2e4."],["Caution.","\uc8fc\uc758."],["Do not use your company's actual sales or customer data in this exercise. Use only the fictional course data.","\ubcf8\uc778 \ud68c\uc0ac\uc758 \uc2e4\uc81c \ub9e4\ucd9c/\uace0\uac1d \ub370\uc774\ud130\ub294 \uc774 \uc2e4\uc2b5\uc5d0\uc11c \uc4f0\uc9c0 \uc54a\ub294\ub2e4. \uac15\uc758 \uc790\ub8cc\uc758 \uac00\uc0c1 \ub370\uc774\ud130\ub85c\ub9cc \uc9c4\ud589\ud55c\ub2e4."],["Demo 1 \u2014 upload four analysis files","\ub370\ubaa8 1 \u2014 \ubd84\uc11d\uc6a9 \ud30c\uc77c 4\uac1c \uc5c5\ub85c\ub4dc"],["Give Claude the new-product launch data directly.","\uc2e0\uc81c\ud488 \ucd9c\uc2dc \ub370\uc774\ud130\ub97c Claude\uc5d0 \uadf8\ub300\ub85c \ub358\uc838\ubcf8\ub2e4."],["Open a new chat and attach these four files.","\uc0c8 \ucc44\ud305\uc744 \uc5f4\uace0 \ub2e4\uc74c 4\uac1c \ud30c\uc77c\uc744 \ucca8\ubd80\ud55c\ub2e4."],["Demo 1 \u2014 run three prompts in order","\ub370\ubaa8 1 \u2014 \ud504\ub86c\ud504\ud2b8 3\uac1c \uc21c\uc11c\ub300\ub85c \uc2e4\ud589"],["See how changing the audience changes the result from the same data.","\uac19\uc740 \ub370\uc774\ud130, \ub3c5\uc790\ub9cc \ubc14\ub00c\uba74 \uacb0\uacfc\uac00 \uc5b4\ub5bb\uac8c \ubc14\ub00c\ub294\uc9c0 \ubcf8\ub2e4."],["Copy","\ubcf5\uc0ac"],["The attached files contain launch data for Morning Brew Lab's unsweetened RTD cold brew, \u201cBrewFit Light.\u201d\nWrite a one-page analysis memo for the CEO.\n\nInclude:\n1. Three key judgments so far\n2. Channel performance comparison\n3. Purchase motives and complaints from the customer survey\n4. Position relative to competitors\n5. Key messages for next quarter's business plan\n\nPlease:\n- Ground all numbers in the attached data.\n- Do not invent external market figures you do not know.\n- End with a separate \u201cAdditional data to verify\u201d section.","\ucca8\ubd80\ud55c \uc790\ub8cc\ub294 \ubaa8\ub2dd\ube0c\ub8e8\ub7a9\uc758 \ubb34\uac00\ub2f9 RTD \ucf5c\ub4dc\ube0c\ub8e8 \"\ube0c\ub8e8\ud54f \ub77c\uc774\ud2b8\" \ucd9c\uc2dc \ub370\uc774\ud130\uc785\ub2c8\ub2e4.\n\n\ub300\ud45c\uc5d0\uac8c \ubcf4\uace0\ud560 1\ud398\uc774\uc9c0 \ubd84\uc11d \uba54\ubaa8\ub97c \uc791\uc131\ud574\uc8fc\uc138\uc694.\n\n\ubc18\ub4dc\uc2dc \ud3ec\ud568\ud560 \ub0b4\uc6a9:\n1. \ud604\uc7ac\uae4c\uc9c0\uc758 \ud575\uc2ec \ud310\ub2e8 3\uac1c\n2. \ucc44\ub110\ubcc4 \uc131\uacfc \ube44\uad50\n3. \uace0\uac1d \uc124\ubb38\uc5d0\uc11c \ubcf4\uc774\ub294 \uad6c\ub9e4 \uc774\uc720\uc640 \ubd88\ub9cc\n4. \uacbd\uc7c1\uc0ac \ub300\ube44 \ud3ec\uc9c0\uc158\n5. \ub2e4\uc74c \ubd84\uae30 \uc0ac\uc5c5\uacc4\ud68d\uc11c\uc5d0 \ub123\uc5b4\uc57c \ud560 \ud575\uc2ec \uba54\uc2dc\uc9c0\n\n\uc8fc\uc758:\n- \uc22b\uc790\ub294 \ucca8\ubd80 \ub370\uc774\ud130\uc5d0\uc11c \uadfc\uac70\ub97c \ucc3e\uc544\uc8fc\uc138\uc694.\n- \ubaa8\ub974\ub294 \uc678\ubd80 \uc2dc\uc7a5 \uc218\uce58\ub294 \ub9cc\ub4e4\uc9c0 \ub9c8\uc138\uc694.\n- \ub9c8\uc9c0\ub9c9\uc5d0 \"\ucd94\uac00\ub85c \ud655\uc778\ud574\uc57c \ud560 \ub370\uc774\ud130\"\ub97c \ub530\ub85c \uc801\uc5b4\uc8fc\uc138\uc694."],["Based on the analysis above, create a five-slide presentation outline.\n\nFor each slide, include:\n- Slide title\n- One-sentence key message\n- Table or chart to include\n- Presenter notes","\uc704 \ubd84\uc11d\uc744 \ubc14\ud0d5\uc73c\ub85c 5\uc7a5\uc9dc\ub9ac \ubc1c\ud45c\uc790\ub8cc \ubaa9\ucc28\ub97c \ub9cc\ub4e4\uc5b4\uc8fc\uc138\uc694.\n\n\uac01 \uc7a5\ub9c8\ub2e4:\n- \uc2ac\ub77c\uc774\ub4dc \uc81c\ubaa9\n- \ud575\uc2ec \uba54\uc2dc\uc9c0 \ud55c \ubb38\uc7a5\n- \ub4e4\uc5b4\uac08 \ud45c \ub610\ub294 \uadf8\ub798\ud504\n- \ubc1c\ud45c\uc790\uac00 \ub9d0\ud560 \ucf54\uba58\ud2b8\n\n\ub97c \ud3ec\ud568\ud574\uc8fc\uc138\uc694."],["Now assume the same material is being presented to investors. Rework the story around \u201cwhy we should push this product further now.\u201d\nAvoid exaggeration and retain only claims defensible with the data.","\uc774\ubc88\uc5d0\ub294 \uac19\uc740 \ub0b4\uc6a9\uc744 \ud22c\uc790\uc790\uc5d0\uac8c \uc124\uba85\ud55c\ub2e4\uace0 \uac00\uc815\ud558\uace0, \"\uc65c \uc9c0\uae08 \uc774 \uc81c\ud488\uc744 \ub354 \ubc00\uc5b4\uc57c \ud558\ub294\uc9c0\" \uc911\uc2ec\uc73c\ub85c \uc2a4\ud1a0\ub9ac\ub97c \ubc14\uafd4\uc8fc\uc138\uc694.\n\uacfc\uc7a5\ub41c \ud45c\ud604\uc740 \ud53c\ud558\uace0, \ub370\uc774\ud130\ub85c \ubc29\uc5b4 \uac00\ub2a5\ud55c \uc8fc\uc7a5\ub9cc \ub0a8\uaca8\uc8fc\uc138\uc694."],["What to observe.","\uad00\ucc30 \ud3ec\uc778\ud2b8."],["Compare the tone of prompts 1 and 3, and distinguish what comes from the data from what is interpretation.","1\ubc88\uacfc 3\ubc88\uc758 \"\ud1a4\"\uc774 \uc5b4\ub5bb\uac8c \ub2e4\ub978\uc9c0, \uc5b4\ub514\uae4c\uc9c0\uac00 \ub370\uc774\ud130\uc5d0\uc11c \uc628 \uac83\uc774\uace0 \uc5b4\ub514\ubd80\ud130\uac00 \ud574\uc11d\uc778\uc9c0 \ube44\uad50\ud55c\ub2e4."],["Look inside a Skill","Skill\uc758 \ubaa8\uc591 \ub4e4\uc5ec\ub2e4\ubcf4\uae30"],["Open the \u201cworking method stored in a folder.\u201d","\"\ud3f4\ub354\ub85c \uc800\uc7a5\ub41c \uc77c\ud558\ub294 \ubc95\"\uc744 \uc9c1\uc811 \uc5f4\uc5b4\ubcf8\ub2e4."],["Open the folder's three files in a text editor.","\ud3f4\ub354\uc758 3\uac1c \ud30c\uc77c\uc744 \ud14d\uc2a4\ud2b8 \uc5d0\ub514\ud130\ub85c \uc5f4\uc5b4\ubcf8\ub2e4."],["\u2014 Procedure, quality criteria and prohibited actions","\u2014 \uc791\uc5c5 \uc808\ucc28, \ud488\uc9c8 \uae30\uc900, \uae08\uc9c0 \ud56d\ubaa9"],["\u2014 Report format","\u2014 \ubcf4\uace0\uc11c \uc591\uc2dd"],["\u2014 Tone and preferred / avoided wording","\u2014 \ub9d0\ud22c, \uc120\ud638/\ud68c\ud53c \ud45c\ud604"],["Write one sentence about the role each file plays.","\uac01 \ud30c\uc77c\uc774 \uc5b4\ub5a4 \uc5ed\ud560\uc744 \ubd84\ub2f4\ud558\uace0 \uc788\ub294\uc9c0 \ud55c \ubb38\uc7a5\uc73c\ub85c \ub178\ud2b8\ud574\ubcf8\ub2e4."],["Example: SKILL.md describes \u201cwhat to do,\u201d report_template.md defines \u201cwhat it should look like,\u201d and style_guide.md sets \u201chow it should sound.\u201d","\uc608: SKILL.md\ub294 '\ubb58 \ud55c\ub2e4'\ub97c, report_template.md\ub294 '\uc5b4\ub5a4 \ubaa8\uc591\uc73c\ub85c'\ub97c, style_guide.md\ub294 '\uc5b4\ub5a4 \ub9d0\ud22c\ub85c'\ub97c \ub2f4\ub2f9\ud558\ub294 \uac83 \uac19\ub2e4."],["This note saves automatically (only in this browser).","\uc774 \uba54\ubaa8\ub294 \uc790\ub3d9 \uc800\uc7a5\ub429\ub2c8\ub2e4 (\ube0c\ub77c\uc6b0\uc800 \ub85c\uceec\uc5d0\ub9cc)."],["Demo 2 \u2014 run the weekly-report Skill","\ub370\ubaa8 2 \u2014 \uc8fc\uac04\ubcf4\uace0 Skill \ub3cc\ub824\ubcf4\uae30"],["Upload six files \u2192 run three prompts in order.","\ud30c\uc77c 6\uac1c \uc5c5\ub85c\ub4dc \u2192 \ud504\ub86c\ud504\ud2b8 3\uac1c \uc21c\uc11c\ub300\ub85c."],["Open a new chat and attach these six files.","\uc0c8 \ucc44\ud305\uc744 \uc5f4\uace0 \ub2e4\uc74c 6\uac1c \ud30c\uc77c\uc744 \ucca8\ubd80\ud55c\ub2e4."],["Use the attached SKILL.md, report template and style guide as working instructions.\nWrite a weekly report for the CEO based on weekly_kpi.csv, support_tickets.csv and field_notes.md.\n\nIn particular:\n- Start with a one-line judgment of this week.\n- Interpret KPI figures alongside customer-support issues.\n- Present at most three decisions for the CEO.\n- Distinguish facts from estimates.","\ucca8\ubd80\ud55c SKILL.md, \ubcf4\uace0\uc11c \ud15c\ud50c\ub9bf, \uc2a4\ud0c0\uc77c \uac00\uc774\ub4dc\ub97c \uc791\uc5c5 \uc9c0\uce68\uc73c\ub85c \uc0ac\uc6a9\ud574\uc8fc\uc138\uc694.\nweekly_kpi.csv, support_tickets.csv, field_notes.md\ub97c \ubc14\ud0d5\uc73c\ub85c \ub300\ud45c \ubcf4\uace0\uc6a9 \uc8fc\uac04\ubcf4\uace0\ub97c \uc791\uc131\ud574\uc8fc\uc138\uc694.\n\n\ud2b9\ud788 \ub2e4\uc74c\uc744 \uc9c0\ucf1c\uc8fc\uc138\uc694:\n- \uccab \ubb38\ub2e8\uc5d0 \uc774\ubc88 \uc8fc \ud55c \uc904 \ud310\ub2e8\uc744 \uc368\uc8fc\uc138\uc694.\n- KPI \uc22b\uc790\uc640 \uace0\uac1d\uc9c0\uc6d0 \uc774\uc288\ub97c \uc5f0\uacb0\ud574\uc11c \ud574\uc11d\ud574\uc8fc\uc138\uc694.\n- \ub300\ud45c\uac00 \uacb0\uc815\ud574\uc57c \ud560 \uc548\uac74\uc740 \ucd5c\ub300 3\uac1c\ub9cc \uc81c\uc2dc\ud574\uc8fc\uc138\uc694.\n- \uc0ac\uc2e4\uacfc \ucd94\uc815\uc744 \uad6c\ubd84\ud574\uc8fc\uc138\uc694."],["From the weekly report you just wrote, extract only the decisions the CEO needs to make in the meeting and turn them into a meeting agenda.\n\nFor each item, include:\n- Decision question\n- Options\n- Recommendation\n- Evidence\n- Risk of not deciding","\ubc29\uae08 \uc791\uc131\ud55c \uc8fc\uac04\ubcf4\uace0\uc5d0\uc11c \"\ub300\ud45c\uac00 \ud68c\uc758\uc5d0\uc11c \ubc14\ub85c \uacb0\uc815\ud574\uc57c \ud558\ub294 \uc548\uac74\"\ub9cc \ubf51\uc544 \ud68c\uc758 \uc544\uc820\ub2e4\ub85c \ubc14\uafd4\uc8fc\uc138\uc694.\n\n\uac01 \uc548\uac74\uc740:\n- \uacb0\uc815 \uc9c8\ubb38\n- \uc120\ud0dd\uc9c0\n- \ucd94\ucc9c\uc548\n- \uadfc\uac70\n- \uacb0\uc815\ud558\uc9c0 \uc54a\uc744 \ub54c\uc758 \ub9ac\uc2a4\ud06c\n\n\ud615\uc2dd\uc73c\ub85c \uc791\uc131\ud574\uc8fc\uc138\uc694."],["I want to reuse this reporting method.\nSuggest five rules to add to the attached SKILL.md to improve it.","\uc774 \ubcf4\uace0\uc11c \uc791\uc131 \ubc29\uc2dd\uc744 \ub2e4\uc74c\uc5d0\ub3c4 \uc7ac\uc0ac\uc6a9\ud558\ub824\uace0 \ud569\ub2c8\ub2e4.\n\uc9c0\uae08 \ucca8\ubd80\ud55c SKILL.md\ub97c \ub354 \uc88b\uac8c \ub9cc\ub4e4\uae30 \uc704\ud574 \ucd94\uac00\ud558\uba74 \uc88b\uc744 \uaddc\uce59 5\uac1c\ub97c \uc81c\uc548\ud574\uc8fc\uc138\uc694."],["Compare whether attaching the Skill makes the output's tone and structure more consistent than Demo 1.","Skill\uc744 \ud568\uaed8 \ucca8\ubd80\ud588\uc744 \ub54c \uacb0\uacfc\uc758 \ud1a4\u00b7\uad6c\uc870\uac00 \ub370\ubaa8 1\ubcf4\ub2e4 \uc77c\uad00\uc801\uc778\uc9c0 \ube44\uad50\ud55c\ub2e4."],["Bring it to your work \u2014 choose one recurring document","\ub0b4 \uc5c5\ubb34\ub85c \uac00\uc838\uc624\uae30 \u2014 \ubc18\ubcf5 \ubb38\uc11c \ud558\ub098 \uace0\ub974\uae30"],["Choose a candidate for your own Skill.","\uc55e\uc73c\ub85c \ub0b4\uac00 Skill\ub85c \ub9cc\ub4e4 \ud6c4\ubcf4\ub97c \uc815\ud55c\ub2e4."],["Answer the following questions.","\ub2e4\uc74c \uc9c8\ubb38\uc5d0 \ub2f5\ud574\ubcf8\ub2e4."],["Which document do you write every week or month?","\ub9e4\uc8fc/\ub9e4\uc6d4 \ubc18\ubcf5\ud574\uc11c \uc4f0\ub294 \ubb38\uc11c\ub294?"],["Where are two good examples and one poor example of that document?","\uadf8 \ubb38\uc11c\uc758 \uc88b\uc740 \uc0d8\ud50c 2\uac1c\uc640 \ubcc4\ub85c\uc600\ub358 \uc0d8\ud50c 1\uac1c\ub294 \uc5b4\ub514 \uc788\ub294\uac00?"],["Which format, tone and judgment criteria must always be followed?","\uadf8 \ubb38\uc11c\uc5d0\uc11c \"\uc774\uac74 \uaf2d \uc9c0\ucf1c\uc57c \ud55c\ub2e4\"\ub294 \uc591\uc2dd\u00b7\ub9d0\ud22c\u00b7\ud310\ub2e8 \uae30\uc900\uc740?"],["Example \u2014 Document: weekly sales-meeting minutes. Good examples: the second week of December 2024 and first week of March 2025. Poor example: the third week of January 2025 (missing action items). Rules: require a four-column table for decision / action / owner / deadline; omit small talk.","\uc608\uc2dc \u2014 \ubb38\uc11c: \uc601\uc5c5 \uc8fc\uac04 \ubbf8\ud305 \ud68c\uc758\ub85d. \uc88b\uc740 \uc0d8\ud50c: 24\ub144 12\uc6d4 \ub458\uc9f8\uc8fc, 25\ub144 3\uc6d4 \uccab\uc8fc. \uc548 \uc88b\uc558\ub358 \uc0d8\ud50c: 25\ub144 1\uc6d4 \uc14b\uc9f8\uc8fc(\uc561\uc158 \uc544\uc774\ud15c\uc774 \ube60\uc9d0). \uaddc\uce59: \uacb0\uc815-\uc561\uc158-\ub2f4\ub2f9\uc790-\uae30\ud55c 4\uceec\ub7fc \ud45c \ud544\uc218, \uc7a1\ub2f4\uc740 \ube7c\uae30."],["Saves automatically.","\uc790\ub3d9 \uc800\uc7a5\ub429\ub2c8\ub2e4."],["Draft your first Skill","\ub0b4 \uccab Skill \ucd08\uc548 \ub9cc\ub4e4\uae30"],["Have Claude write a first draft of SKILL.md.","Claude\uc5d0\uac8c \uc9c1\uc811 SKILL.md \ucd08\uc548\uc744 \uc9dc\uac8c \ud55c\ub2e4."],["Copy the prompt below, insert your answers from step 6, and send it to Claude.","\uc544\ub798 \ud504\ub86c\ud504\ud2b8\ub97c \ubcf5\uc0ac\ud574\uc11c \ub2e8\uacc4 6\uc758 \ub2f5\uc744 \ub123\uace0 Claude\uc5d0 \ubcf4\ub0b8\ub2e4."],["I write [task/document name] every week.\n\nGood examples: [key features of examples 1 and 2]\nPoor example: [what went wrong in example 3]\nRequired rules: [format/tone/judgment criteria]\n\nDraft a SKILL.md that helps me do this task consistently next time.\n\nInclude these sections:\n- Purpose\n- Input materials\n- Working procedure\n- Quality criteria\n- Prohibited actions\n\nIf anything is missing, end with a separate \u201cWhat else you need to tell me\u201d list.","\uc800\ub294 [\uc5c5\ubb34/\ubb38\uc11c \uc774\ub984]\uc744 \ub9e4\uc8fc \ubc18\ubcf5\ud574\uc11c \uc791\uc131\ud569\ub2c8\ub2e4.\n\n\uc88b\uc740 \uc0d8\ud50c: [\uc0d8\ud50c 1, 2\uc758 \ud575\uc2ec \ud2b9\uc9d5]\n\uc548 \uc88b\uc558\ub358 \uc0d8\ud50c: [\uc0d8\ud50c 3\uc5d0\uc11c \ubb38\uc81c\uac00 \ub41c \uc810]\n\uc9c0\ucf1c\uc57c \ud560 \uaddc\uce59: [\uc591\uc2dd/\ub9d0\ud22c/\ud310\ub2e8 \uae30\uc900]\n\n\uc774 \uc791\uc5c5\uc744 \ub2e4\uc74c\uc5d0\ub3c4 \uc77c\uad00\ub418\uac8c \ud558\uae30 \uc704\ud55c SKILL.md \ucd08\uc548\uc744 \uc791\uc131\ud574\uc8fc\uc138\uc694.\n\n\ub2e4\uc74c \uc139\uc158\uc744 \ud3ec\ud568\ud574\uc8fc\uc138\uc694:\n- \ubaa9\uc801\n- \uc785\ub825 \uc790\ub8cc\n- \uc791\uc5c5 \uc808\ucc28\n- \ud488\uc9c8 \uae30\uc900\n- \uae08\uc9c0 \ud56d\ubaa9\n\n\ube60\uc9c4 \ud56d\ubaa9\uc774 \uc788\uc73c\uba74 \ub9c8\uc9c0\ub9c9\uc5d0 \"\ucd94\uac00\ub85c \uc54c\ub824\uc8fc\uc154\uc57c \ud560 \uac83\" \ubaa9\ub85d\uc73c\ub85c \ub530\ub85c \uc801\uc5b4\uc8fc\uc138\uc694."],["This is not the end.","\uc774\uac8c \ub05d\uc774 \uc544\ub2c8\ub2e4."],["Claude's follow-up questions reveal rules you have not yet articulated. Add your answers to SKILL.md and run it once more to complete a first version.","Claude\uac00 \ub418\ubb3b\ub294 \ud56d\ubaa9\uc774 \uace7 \ub0b4\uac00 \ubbf8\ucc98 \uc815\ub9ac\ud558\uc9c0 \ubabb\ud55c \uaddc\uce59\uc774\ub2e4. \uadf8 \ub2f5\uc744 SKILL.md\uc5d0 \ub2e4\uc2dc \ub123\uace0 \ud55c \ubc88 \ub354 \ub3cc\ub9ac\uba74 1\ucc28 \uc644\uc131\uc774\ub2e4."],["Checkmarks and notes are stored only in this browser \u00b7 Send course feedback directly to the instructor","\uccb4\ud06c \uc0c1\ud0dc\uc640 \uba54\ubaa8\ub294 \uc774 \ube0c\ub77c\uc6b0\uc800\uc5d0\ub9cc \uc800\uc7a5\ub429\ub2c8\ub2e4 \u00b7 \uac15\uc758\uc790\ub8cc\uc5d0 \ub300\ud55c \ud53c\ub4dc\ubc31\uc740 \uac15\uc0ac\uc5d0\uac8c \uc9c1\uc811 \uc804\ub2ec\ud574\uc8fc\uc138\uc694"],["Copied","\ubcf5\uc0ac\ub428"],["Reset all checkmarks and notes. Continue?","\ubaa8\ub4e0 \uccb4\ud06c\uc640 \uba54\ubaa8\ub97c \ucd08\uae30\ud654\ud569\ub2c8\ub2e4. \uacc4\uc18d\ud560\uae4c\uc694?"]];
